import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_3x3_bf16_forward(torch::Tensor x, torch::Tensor w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_bf16.h>
#include <cuda_pipeline.h>
#include <mma.h>

#include <cute/tensor.hpp>

using namespace cute;
using namespace nvcuda;

// Tensor-core implicit-GEMM 3x3, stride-1, pad-0 convolution specialized for CIN=3.
//  - Each CTA computes a GEMM tile of M=32 output channels x N=512 outputs
//    (a 32x16 spatial output tile) for one batch.
//  - K = CIN*3*3 = 27 is zero-padded to 32 and consumed as two 16-wide K chunks.
//  - Weights (A: 32x32, row-major) and the im2col input tile (B: 32x512,
//    row-major) are staged in shared memory via CUTE tensors, then 8 warps
//    cooperate through bf16 WMMA (m16n16k16) with fp32 accumulation.
template <typename T, int CIN>
__global__ __launch_bounds__(256)
void conv2d_3x3_s1p0_kernel(const T* __restrict__ Xp,
                            const T* __restrict__ Wp,
                            T* __restrict__ Yp,
                            int N, int H, int W,
                            int Cout, int Hout, int Wout)
{
  constexpr int TILE_H  = 32;
  constexpr int TILE_W  = 16;
  constexpr int M_TILE  = 32;
  constexpr int N_TILE  = TILE_H * TILE_W;  // 512 GEMM columns
  constexpr int K_TILE  = 32;               // CIN*9 = 27 zero-padded to 32
  constexpr int THREADS = 256;
  constexpr int WARPS   = THREADS / 32;
  constexpr int WARP_N  = N_TILE / WARPS;   // 64 GEMM columns per warp
  constexpr int N_FRAG  = WARP_N / 16;      // 16-wide fragments per warp
  constexpr int HALO_H  = TILE_H + 2;   // 34 input rows touched by this tile
  constexpr int HALO_W  = TILE_W + 2;   // 18 input cols touched by this tile
  constexpr int HALO_WP = 24;           // padded halo row (16B-aligned smem rows)
  // Bank-conflict reduction: skew the smem operand row strides so the rows of
  // each 16x16 WMMA fragment no longer alias onto the same shared-memory banks.
  // Both strides stay multiples of 8 elements (16B rows) to keep WMMA legal.
  constexpr int LD_A    = K_TILE + 8;   // padded A row stride (40 elems, 80B)
  constexpr int LD_B    = N_TILE + 8;   // padded B row stride (520 elems, 1040B)
  const int tid     = threadIdx.x;
  const int lane    = tid & 31;
  const int warp    = tid >> 5;
  const int n       = blockIdx.z;
  const int tiles_x = (Wout + TILE_W - 1) / TILE_W;
  const int tile_y  = blockIdx.x / tiles_x;
  const int tile_x  = blockIdx.x - tile_y * tiles_x;
  const int oh0 = tile_y * TILE_H;
  const int ow0 = tile_x * TILE_W;
  const int co0 = blockIdx.y * M_TILE;
  // Global tensors described with CUTE layouts
  Tensor mX = make_tensor(make_gmem_ptr(Xp),
                          make_shape(N, Int<CIN>{}, H, W),
                          make_stride((int64_t)CIN * H * W, (int64_t)H * W, (int64_t)W, _1{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wp),
                          make_shape(Cout, Int<CIN>{}, _9{}),
                          make_stride((int64_t)CIN * 9, _9{}, _1{}));
  Tensor mY = make_tensor(make_gmem_ptr(Yp),
                          make_shape(N, Cout, Hout, Wout),
                          make_stride((int64_t)Cout * Hout * Wout, (int64_t)Hout * Wout,
                                      (int64_t)Wout, _1{}));
  // Shared operands (K is zero-padded); ~43KB static smem, no opt-in needed
  __shared__ alignas(32) T sA[M_TILE * LD_A];      // 32x32 weights, row-major (skewed rows)
  __shared__ alignas(32) T sB[K_TILE * LD_B];      // 32x512 im2col input, row-major (skewed rows)
  __shared__ alignas(16) T sH[CIN * HALO_H * HALO_WP];  // staged input halo tile
  __shared__ alignas(32) float sC[WARPS][16 * 16];  // per-warp 16x16 fp32 stage
  // Stage A: A[m][k] = W[co0 + m][k], k = c*9 + kh*3 + kw (zero when padded)
  for (int idx = tid; idx < M_TILE * K_TILE; idx += THREADS) {
    const int m = idx / K_TILE;
    const int k = idx - m * K_TILE;
    T v = T(0.f);
    if (k < CIN * 9 && co0 + m < Cout) {
      v = mW(co0 + m, k / 9, k % 9);
    }
    sA[m * LD_A + k] = v;
  }
  // Stage B via an input halo tile: fetch each input pixel from gmem once
  // (coalesced, 16B-vectorized when aligned) instead of up to 9x through
  // the K rows of the im2col matrix, then build B[k][nn] from smem.
  for (int idx = tid; idx < CIN * HALO_H * HALO_WP; idx += THREADS) {
    sH[idx] = T(0.f);
  }
  __syncthreads();
  // Stage the halo as 16B chunks so all 256 threads participate. Each input
  // row contributes two full uint4 chunks (16 bf16 values) plus a guarded
  // two-element tail; out-of-range rows/cols stay zero from the clear above.
  const bool halo_vec_ok = ((W & 7) == 0) && ((ow0 & 7) == 0);
  constexpr int CHUNKS_PER_ROW = HALO_W / 8;  // two 16B chunks per 18-col halo row
  for (int chunk = tid; chunk < CIN * HALO_H * CHUNKS_PER_ROW; chunk += THREADS) {
    const int r  = chunk / CHUNKS_PER_ROW;
    const int q  = chunk - r * CHUNKS_PER_ROW;
    const int c  = r / HALO_H;
    const int rh = r - c * HALO_H;
    const int h  = oh0 + rh;
    const int iw = ow0 + q * 8;
    T* dst = &sH[r * HALO_WP + q * 8];
    if (halo_vec_ok && h < H && iw + 7 < W) {
      __pipeline_memcpy_async(dst, &mX(n, c, h, iw), 16);
    } else {
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const int ww = iw + i;
        dst[i] = (h < H && ww < W) ? mX(n, c, h, ww) : T(0.f);
      }
    }
  }
  for (int idx = tid; idx < CIN * HALO_H * (HALO_W - CHUNKS_PER_ROW * 8); idx += THREADS) {
    const int tail = idx & 1;
    const int r    = idx >> 1;
    const int c    = r / HALO_H;
    const int rh   = r - c * HALO_H;
    const int h    = oh0 + rh;
    const int i    = CHUNKS_PER_ROW * 8 + tail;
    const int ww   = ow0 + i;
    if (h < H && ww < W) sH[r * HALO_WP + i] = mX(n, c, h, ww);
  }
  __pipeline_commit();
  __pipeline_wait_prior(0);
  __syncthreads();
  // Build B[k][nn] = sH[c][oh + kh][ow + kw], nn = oh*16 + ow (zero-padded K).
  for (int idx = tid; idx < K_TILE * N_TILE; idx += THREADS) {
    const int k  = idx / N_TILE;
    const int nn = idx - k * N_TILE;
    T v = T(0.f);
    if (k < CIN * 9) {
      const int c  = k / 9;
      const int r  = k - c * 9;
      const int kh = r / 3;
      const int kw = r - kh * 3;
      const int oh = nn >> 4;
      const int ow = nn & 15;
      v = sH[(c * HALO_H + oh + kh) * HALO_WP + ow + kw];
    }
    sB[k * LD_B + nn] = v;
  }
  __syncthreads();
  const __nv_bfloat16* pA = reinterpret_cast<const __nv_bfloat16*>(sA);
  const __nv_bfloat16* pB = reinterpret_cast<const __nv_bfloat16*>(sB);
  // Each warp owns WARP_N consecutive GEMM columns across both 16-row M halves.
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[2][N_FRAG];
  #pragma unroll
  for (int i = 0; i < 2; ++i)
    #pragma unroll
    for (int j = 0; j < N_FRAG; ++j)
      wmma::fill_fragment(acc[i][j], 0.0f);
  #pragma unroll
  for (int kc = 0; kc < K_TILE / 16; ++kc) {
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> fa[2];
    wmma::load_matrix_sync(fa[0], pA + kc * 16, LD_A);
    wmma::load_matrix_sync(fa[1], pA + 16 * LD_A + kc * 16, LD_A);
    #pragma unroll
    for (int j = 0; j < N_FRAG; ++j) {
      wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> fb;
      wmma::load_matrix_sync(fb, pB + kc * 16 * LD_B + warp * WARP_N + j * 16, LD_B);
      wmma::mma_sync(acc[0][j], fa[0], fb, acc[0][j]);
      wmma::mma_sync(acc[1][j], fa[1], fb, acc[1][j]);
    }
  }
  // Write results out through the per-warp fp32 staging tile (bounds-guarded).
  #pragma unroll
  for (int i = 0; i < 2; ++i) {
    #pragma unroll
    for (int j = 0; j < N_FRAG; ++j) {
      wmma::store_matrix_sync(sC[warp], acc[i][j], 16, wmma::mem_row_major);
      __syncwarp();
      const int gn0 = warp * WARP_N + j * 16;
      for (int e = lane; e < 256; e += 32) {
        const int r  = e >> 4;
        const int cc = e & 15;
        const int co = co0 + i * 16 + r;
        const int gn = gn0 + cc;
        const int oh = oh0 + (gn >> 4);
        const int ow = ow0 + (gn & 15);
        if (co < Cout && oh < Hout && ow < Wout) {
          mY(n, co, oh, ow) = static_cast<T>(sC[warp][e]);
        }
      }
      __syncwarp();
    }
  }
}

torch::Tensor conv2d_3x3_bf16_forward(torch::Tensor x, torch::Tensor w) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16 && w.scalar_type() == at::kBFloat16,
              "x and w must be bfloat16");
  TORCH_CHECK(x.dim() == 4 && w.dim() == 4, "x:[N,C,H,W], w:[Cout,Cin,3,3]");
  TORCH_CHECK(w.size(2) == 3 && w.size(3) == 3, "kernel size must be 3x3");

  const int64_t N    = x.size(0);
  const int64_t CIN  = x.size(1);
  const int64_t H    = x.size(2);
  const int64_t W    = x.size(3);
  const int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == CIN, "weight/input channel mismatch");
  TORCH_CHECK(CIN == 3, "this kernel is specialized for 3 input channels");

  const int64_t Hout = H - 2;  // stride=1, pad=0, k=3
  const int64_t Wout = W - 2;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid spatial sizes");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  auto y   = torch::empty({N, Cout, Hout, Wout}, x.options());

  using T = cute::bfloat16_t;
  constexpr int TILE_H = 32;
  constexpr int TILE_W = 16;
  constexpr int COUT_PER_CTA = 32;
  dim3 block(256);
  dim3 grid((unsigned)(((Hout + TILE_H - 1) / TILE_H) * ((Wout + TILE_W - 1) / TILE_W)),
            (unsigned)((Cout + COUT_PER_CTA - 1) / COUT_PER_CTA),
            (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_3x3_s1p0_kernel<T, 3><<<grid, block, 0, stream>>>(
      reinterpret_cast<const T*>(x_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<const T*>(w_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<T*>(y.data_ptr<at::BFloat16>()),
      (int)N, (int)H, (int)W, (int)Cout, (int)Hout, (int)Wout);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_3x3_s1p0_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

