        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3,
                               bias=False, dtype=torch.bfloat16)
        self._ext = conv_ext

    def forward(self, x):
        if not x.is_cuda:
            return F.conv2d(x, self.conv1.weight, None, 1, 0, 1, 1)
        return self._ext.conv2d_3x3_bf16_forward(x, self.conv1.weight)

